import {createHash} from 'node:crypto';
// Private fixture on stdin. Use the built Web application and the real loopback
// user router. No responses are intercepted or generated by the browser test.
import { chromium } from '@playwright/test';
import { preview } from 'vite';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root=fileURLToPath(new URL('../',import.meta.url));
const tls=resolve(root,'../../.local/tls');
let input='';
for await (const chunk of process.stdin) input+=chunk;
const f=JSON.parse(input);
const upstream=new URL(f.api);
if(upstream.protocol!=='http:'||upstream.hostname!=='127.0.0.1'||!upstream.port ||
    f.origin!=='https://127.0.0.1:43122' || typeof f.token!=='string')throw Error('Expected a private loopback user fixture');
const server=await preview({root,configFile:false,logLevel:'silent',preview:{host:'127.0.0.1',port:43122,strictPort:true,
  https:{key:readFileSync(resolve(tls,'key.pem')),cert:readFileSync(resolve(tls,'cert.pem'))},
  proxy:{'/api/v1/':{target:upstream.origin,changeOrigin:false}}}});
let browser;
try {
  browser=await chromium.launch({channel:'chrome',headless:true});
  const context=await browser.newContext({baseURL:f.origin,ignoreHTTPSErrors:true,viewport:{width:1280,height:960}});
  await context.addCookies([{name:'__Host-orange-user',value:f.token,url:f.origin,secure:true,httpOnly:true,sameSite:'Lax'}]);
  const page=await context.newPage();
  page.setDefaultTimeout(15000);
  const route='/agent/runs/'+encodeURIComponent(f.run)+'/confluence';
  await page.goto(route);
  await page.getByRole('combobox',{name:'Confluence 站点'}).click();
  await page.locator('.ant-select-item-option-content').filter({hasText:'example.atlassian.net'}).click();
  await page.getByRole('checkbox',{name:'ops · OPS'}).check();
  const newGrant=page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname.endsWith('/connectors/confluence'));
  await page.getByRole('button',{name:'授权所选空间 15 分钟'}).click();
  const receipt=await (await newGrant).json();
  if(!receipt.grant_id)throw Error('No space grant');
  const section=page.getByRole('region',{name:'空间授权 '+receipt.grant_id});
  await section.getByLabel('搜索标题').fill('release');
  await section.getByRole('button',{name:'搜索 ops 页面'}).click();
  await section.getByRole('button',{name:'Page 11',exact:true}).click();
  await section.locator('pre').filter({hasText:'Visible page text[mention]'}).waitFor();
  await section.getByRole('button',{name:'查看子页面'}).click();
  await section.getByRole('button',{name:'Page 12',exact:true}).waitFor();
  await section.getByRole('button',{name:'搜索 ops 页面'}).click();
  await section.getByRole('button',{name:'Page 11',exact:true}).click();
  await section.getByRole('button',{name:'将 report.txt 保存到隔离区'}).click();
  const download=page.waitForEvent('download');
  await section.getByRole('button',{name:'下载已校验的隔离附件'}).click();
  const file=await download;
  if(file.suggestedFilename()!=='report.txt')throw Error('Attachment filename mismatch');
  const bytes=readFileSync(await file.path());
  const digest=createHash('sha256').update(bytes).digest('hex');
  if(bytes.length!==3145728||digest!==createHash('sha256').update(Buffer.alloc(3145728,0x43)).digest('hex'))throw Error('Quarantine download content mismatch');
  if(f.screenshot)await page.screenshot({path:f.screenshot,fullPage:true});
  await section.getByRole('button',{name:'撤销空间授权'}).click();
  await section.getByText('已撤销',{exact:true}).waitFor();
  await page.reload();
  await section.getByText('已撤销',{exact:true}).waitFor();
  if(await section.getByRole('button',{name:'下载已校验的隔离附件'}).count())throw Error('Revoked action visible');
  process.stdout.write(JSON.stringify({searched:true,page:true,children:true,quarantine:true,downloaded_bytes:bytes.length,sha256:digest,revoked_after_reload:true})+'\n');
} finally {
  if(browser)await browser.close();
  await server.close();
}
